import 'dart:convert';
import 'dart:io';

import 'package:open_memex_app/src/db.dart';
import 'package:sqlite3/sqlite3.dart';

/// Path of the app schema fixture generated by #3's
/// `crates/memex-core/tests/schema_dump.rs`. Never edit it by hand. It keeps
/// its V5 name, but since #415 it holds a fresh vault's current (V7) schema:
/// tables, indexes, the `content_revision_<table>_{ai,au,ad}` triggers, then
/// the rows, with the `content_revision` row `(1, 0)` last.
/// `flutter test` runs with the package root (`app/`) as cwd.
const vaultSchemaV5FixturePath = 'test/fixtures/vault_schema_v5.sql';

/// The schema version of the fixture: a fresh vault of the current `memex`.
/// It can be newer than the app's `requiredVaultSchemaVersion`.
const fixtureSchemaVersion = 7;

/// Tables that schema V5 adds (absent from a V4 vault).
const v5Tables = <String>[
  'blocks',
  'day_reviews',
  'day_review_blocks',
  'footer_chips',
  'agent_changes',
  'smart_folders',
  'smart_folder_members',
  'vault_settings',
];

/// Tables that schema V6 adds (absent from a V5 vault).
const v6Tables = <String>[
  'tag_corrections',
  'feedback',
  'vault_guide_revisions',
];

/// Columns that schema V6 adds to `tags`.
const v6TagColumns = <String>['origin', 'first_line'];

/// Tables that schema V7 adds (absent from a V6 vault). `content_revision`
/// is last: it goes only after every trigger that writes it.
const v7Tables = <String>[
  'agent_activity',
  'learned_words',
  'content_revision',
];

/// The `tags` table and index as V2..V5 shipped them.
const _v5TagsDdl = """
CREATE TABLE tags (
    note_id TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
    tag     TEXT NOT NULL,
    PRIMARY KEY (note_id, tag)
);
CREATE INDEX idx_tags_tag ON tags(tag);
""";

/// A real [VaultDb] over an in-memory SQLite database loaded from the app
/// schema fixture (D20). Use it as the `vaultDbProvider` override; later WIs
/// add seed helpers as extensions in `test/support/<area>_*.dart`.
class FakeVaultDb extends VaultDb {
  FakeVaultDb._(super.db) : super.fromDatabase();

  /// A fresh vault at the fixture's schema (the default).
  factory FakeVaultDb() => FakeVaultDb.v5();

  /// A fresh vault at the fixture's schema: every fixture statement applied.
  /// Named for V5 (#3); since #415 the fixture is V7, so this is a vault the
  /// app reads in full.
  factory FakeVaultDb.v5() {
    final db = sqlite3.openInMemory();
    db.execute(_fixtureSql());
    return FakeVaultDb._(db);
  }

  /// A fresh vault that has every V6 table: the same as [FakeVaultDb.v5],
  /// named for V6 tests. Since #415 it is at V7; [FakeVaultDb.v6Only] is a
  /// vault exactly at V6.
  factory FakeVaultDb.v6() => FakeVaultDb.v5();

  /// A vault exactly at schema V6: the fixture without the V7 tables
  /// (`agent_activity`, `learned_words`, `content_revision`), without any
  /// `content_revision_*` trigger and without the `schema_version` row 7.
  /// [migrateToV6] simulates the CLI's migration on the same handle.
  factory FakeVaultDb.v6Only() {
    final db = sqlite3.openInMemory();
    db.execute(_fixtureSql());
    _downgradeToV6(db);
    return FakeVaultDb._(db);
  }

  /// A vault exactly at schema V5: the fixture without the V6 tables, the V6
  /// index on `notes`, the V6 `tags` columns and the `schema_version` row 6.
  /// [migrateToV6] simulates the CLI's migration on the same handle.
  factory FakeVaultDb.v5Only() {
    final db = sqlite3.openInMemory();
    db.execute(_fixtureSql());
    _downgradeToV5(db);
    return FakeVaultDb._(db);
  }

  /// A V4 vault: the V5 vault of [FakeVaultDb.v5Only] with the V5-only
  /// tables, the V5 index on `notes` and the `schema_version` row 5 removed,
  /// so `MAX(version) = 4`. [migrateToV5] simulates the CLI's migration on
  /// the same handle.
  factory FakeVaultDb.v4() {
    final db = sqlite3.openInMemory();
    db.execute(_fixtureSql());
    _downgradeToV5(db);
    db.execute('DROP INDEX IF EXISTS idx_notes_daily_title');
    for (final t in v5Tables) {
      db.execute('DROP TABLE IF EXISTS $t');
    }
    db.execute('DELETE FROM schema_version WHERE version >= 5');
    return FakeVaultDb._(db);
  }

  /// Removes what V7 adds. The triggers go first: a write to a table whose
  /// trigger names a missing `content_revision` would fail.
  static void _downgradeToV6(Database db) {
    final triggers = db
        .select(
          "SELECT name FROM sqlite_master WHERE type = 'trigger' "
          r"AND name LIKE 'content\_revision\_%' ESCAPE '\'",
        )
        .map((r) => r['name'] as String)
        .toList();
    for (final t in triggers) {
      db.execute('DROP TRIGGER IF EXISTS "$t"');
    }
    for (final t in v7Tables) {
      db.execute('DROP TABLE IF EXISTS $t');
    }
    db.execute('DELETE FROM schema_version WHERE version >= 7');
  }

  static void _downgradeToV5(Database db) {
    _downgradeToV6(db);
    db.execute('DROP INDEX IF EXISTS idx_notes_guide');
    for (final t in v6Tables.reversed) {
      db.execute('DROP TABLE IF EXISTS $t');
    }
    final tagColumns = _columns(db, 'tags');
    if (v6TagColumns.any(tagColumns.contains)) {
      db.execute('DROP TABLE tags');
      db.execute(_v5TagsDdl);
    }
    db.execute('DELETE FROM schema_version WHERE version >= 6');
  }

  static Set<String> _columns(Database db, String table) => db
      .select('SELECT name FROM pragma_table_info(?)', [table])
      .map((r) => r['name'] as String)
      .toSet();

  /// What `memex settings get` does to an older vault: it migrates it to the
  /// current schema in one go. Same as [migrateToV6]; the name is kept for
  /// the V4 tests.
  void migrateToV5() => migrateToV6();

  /// What `memex` does to an older vault on open: replay the fixture
  /// idempotently on this same database handle (the app's handle stays open
  /// while the CLI migrates, as in production), then give `tags` the
  /// fixture's columns, keeping its rows. With [tagColumns] false the `tags`
  /// table is left as it was (a vault with the V6 tables but not the V6
  /// columns). Replaying twice changes nothing: every `CREATE` gets
  /// `IF NOT EXISTS` (triggers included) and every `INSERT` is
  /// `INSERT OR IGNORE`, so `content_revision` keeps its `n`.
  void migrateToV6({bool tagColumns = true}) {
    for (final stmt in _fixtureStatements()) {
      db.execute(_idempotent(stmt));
    }
    if (tagColumns) {
      _upgradeTagsTable();
      // A rebuilt `tags` lost its revision triggers with the old table.
      for (final stmt in _fixtureStatements()) {
        if (stmt.startsWith('CREATE TRIGGER ')) db.execute(_idempotent(stmt));
      }
    }
  }

  /// [stmt] made safe to run over objects and rows that already exist.
  static String _idempotent(String stmt) => stmt
      .replaceFirst(
        RegExp(r'^CREATE TABLE ', multiLine: false),
        'CREATE TABLE IF NOT EXISTS ',
      )
      .replaceFirst(
        RegExp(r'^CREATE UNIQUE INDEX '),
        'CREATE UNIQUE INDEX IF NOT EXISTS ',
      )
      .replaceFirst(RegExp(r'^CREATE INDEX '), 'CREATE INDEX IF NOT EXISTS ')
      .replaceFirst(
        RegExp(r'^CREATE TRIGGER '),
        'CREATE TRIGGER IF NOT EXISTS ',
      )
      .replaceFirst(RegExp(r'^INSERT INTO '), 'INSERT OR IGNORE INTO ');

  /// Rebuilds `tags` with the fixture's declaration when it lacks a fixture
  /// column, copying every `(note_id, tag)` row.
  void _upgradeTagsTable() {
    final scratch = sqlite3.openInMemory();
    final String ddl;
    final Set<String> wanted;
    try {
      scratch.execute(_fixtureSql());
      wanted = _columns(scratch, 'tags');
      ddl =
          scratch
                  .select(
                    "SELECT sql FROM sqlite_master WHERE type = 'table' "
                    "AND name = 'tags'",
                  )
                  .first['sql']
              as String;
    } finally {
      scratch.dispose();
    }
    if (wanted.every(_columns(db, 'tags').contains)) return;
    db.execute('ALTER TABLE tags RENAME TO tags_before_v6');
    db.execute(ddl);
    db.execute(
      'INSERT INTO tags (note_id, tag) SELECT note_id, tag FROM tags_before_v6',
    );
    db.execute('DROP TABLE tags_before_v6');
    db.execute('CREATE INDEX IF NOT EXISTS idx_tags_tag ON tags(tag)');
  }

  /// `MAX(schema_version.version)`, for test assertions.
  int get schemaVersionForTest =>
      (db.select('SELECT MAX(version) AS v FROM schema_version').first['v']
              as num)
          .toInt();

  /// `content_revision.n`, or null when the vault has no `content_revision`
  /// (a V6 vault), for test assertions.
  int? get contentRevisionForTest {
    final has = db.select(
      "SELECT 1 FROM sqlite_master WHERE type = 'table' "
      "AND name = 'content_revision'",
    );
    if (has.isEmpty) return null;
    final rows = db.select('SELECT n FROM content_revision WHERE id = 1');
    return rows.isEmpty ? null : (rows.first['n'] as num).toInt();
  }

  /// Record [version] as applied (e.g. 8, a vault newer than this app).
  void addSchemaVersion(int version) {
    db.execute('INSERT OR IGNORE INTO schema_version(version) VALUES (?)', [
      version,
    ]);
  }

  /// Insert one row into `notes`. [role] is a shortcut for
  /// `frontmatter: '{"role":"<role>"}'`; an explicit [frontmatter] wins.
  /// Timestamps are unix ms. Returns [id].
  String seedNote({
    required String id,
    required String title,
    String content = '',
    String? frontmatter,
    String? role,
    int version = 1,
    int createdAt = 1759500000000,
    int? updatedAt,
    List<String> tags = const [],
  }) {
    final fm =
        frontmatter ?? (role == null ? '{}' : jsonEncode({'role': role}));
    db.execute(
      'INSERT INTO notes (id, title, content_md, frontmatter, version, '
      'created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
      [id, title, content, fm, version, createdAt, updatedAt ?? createdAt],
    );
    for (final tag in tags) {
      db.execute('INSERT INTO tags (note_id, tag) VALUES (?, ?)', [id, tag]);
    }
    return id;
  }

  static String? _cachedSql;

  static String _fixtureSql() =>
      _cachedSql ??= File(vaultSchemaV5FixturePath).readAsStringSync();

  /// The fixture split into statements, each without its final `;`. A
  /// statement ends with `;` at a line end; a `CREATE TRIGGER` ends only at
  /// its `END;`, since its body holds statements of its own.
  static List<String> _fixtureStatements() {
    final out = <String>[];
    final buf = StringBuffer();
    final triggerEnd = RegExp(r'\bEND\s*;$', caseSensitive: false);
    for (final line in _fixtureSql().split('\n')) {
      if (line.trimLeft().startsWith('--')) continue;
      if (buf.isEmpty && line.trim().isEmpty) continue;
      buf.writeln(line);
      final text = buf.toString().trim();
      final done = text.toUpperCase().startsWith('CREATE TRIGGER')
          ? triggerEnd.hasMatch(text)
          : text.endsWith(';');
      if (done) {
        out.add(text.substring(0, text.length - 1).trim());
        buf.clear();
      }
    }
    final rest = buf.toString().trim();
    if (rest.isNotEmpty) out.add(rest);
    return out;
  }
}
